class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        if x != 0 and x % 10 == 0:
            return False
        remaining = x
        reversed_half = 0
        while remaining > reversed_half:
            digit = remaining % 10
            reversed_half = reversed_half * 10 + digit
            remaining //= 10
        return remaining == reversed_half or remaining == reversed_half // 10
```

