class Solution:
    def mySqrt(self, x: int) -> int:
        left, right, answer = 0, x, 0
        while left <= right:
            mid = (left + right) // 2
            square = mid * mid
            if square == x:
                return mid
            if square < x:
                answer = mid
                left = mid + 1
            else:
                right = mid - 1
        return answer
```

