class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n == 0:
            return 1.0
        negative_exponent = n < 0
        exponent = -n if negative_exponent else n
        result = 1.0
        base = x
        while exponent > 0:
            if exponent % 2 == 1:
                result *= base
            base *= base
            exponent //= 2
        if negative_exponent:
            return 1.0 / result
        return result
